# Wrap everything inside card
st.markdown('<div class="main-card">', unsafe_allow_html=True)

st.markdown("""
<div class="brand">
  <span class="brand-icon">🍽️</span>
  <h1>Spice Garden</h1>
  <p>Share your experience with us</p>
</div>
""", unsafe_allow_html=True)

# ── Google Sheet connection ───────────────────────────────────────────────────
def get_sheet():
    scopes = ["https://spreadsheets.google.com/feeds",
              "https://www.googleapis.com/auth/drive"]
    creds_dict = json.loads(st.secrets["GOOGLE_CREDS"])
    creds = Credentials.from_service_account_info(creds_dict, scopes=scopes)
    gc = gspread.authorize(creds)
    return gc.open_by_key(st.secrets["SHEET_ID"]).sheet1

# ── Form ──────────────────────────────────────────────────────────────────────
BRANCHES = [
    "Spice Garden — Koramangala",
    "Spice Garden — Indiranagar",
    "Spice Garden — Whitefield",
    "Spice Garden — JP Nagar",
    "Spice Garden — HSR Layout",
]

branch = st.selectbox("📍 Which branch did you visit?", BRANCHES)

name = st.text_input("👤 Your name ", placeholder="e.g. Rahul")

st.markdown("**⭐ Overall rating**")
star_labels = ["1 — Terrible", "2 — Poor", "3 — Okay", "4 — Good", "5 — Excellent"]
star_icons  = ["😡", "😞", "😐", "😊", "🤩"]
chosen_star = st.radio(
    "Rating", options=[1, 2, 3, 4, 5],
    format_func=lambda x: f"{star_icons[x-1]}  {star_labels[x-1]}",
    horizontal=True, label_visibility="collapsed"
)

review = st.text_area(
    "✍️ Tell us about your experience",
    placeholder="e.g. The biryani was amazing but delivery took too long. Staff was very polite...",
    height=150
)

submitted = st.button("Submit Review →", type="primary", use_container_width=True)

if submitted:
    if not review.strip():
        st.warning("Please write a short review before submitting.")
    else:
        try:
            sheet = get_sheet()
            row = [
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                branch,
                name.strip() or "Anonymous",
                int(chosen_star),
                review.strip(),
                "pending"
            ]
            sheet.append_row(row)
            thanks_html = (
                f'<div class="thanks">✨ Thank you, {name.strip() or "friend"}!<br>'
                f'Your {chosen_star}★ review has been submitted for <strong>{branch}</strong>.<br>'
                f'<span style="font-size:13px;opacity:0.7;margin-top:8px;display:block;">We truly value your feedback.</span></div>'
            )
            st.markdown(thanks_html, unsafe_allow_html=True)
            st.balloons()
        except Exception as e:
            st.error(f"Could not save your review: {e}")

st.markdown("---")
st.caption("Spice Garden · Bangalore · Crafted with care since 2018")
